INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'tshwane-lifts-pretoria-cbd-boil-water-advisory-2026-10-24',
  'Tshwane lifts Pretoria CBD boil-water advisory',
  'Utilities', '2026-10-24', 'The Citizen', 'https://www.citizen.co.za/news/city-of-tshwane-pretoria-cbd-tap-water-bronkhorstspruit/',
  'The City of Tshwane lifted its Pretoria CBD boil-water advisory on Saturday after lab tests found no E. coli in the Findlay Reservoir supply.',
  'The City of Tshwane has lifted its boil-water advisory for the Pretoria CBD and surrounding suburbs supplied by the Findlay Reservoir, Mayor Nasiphi Moya confirmed on Saturday. Residents in the affected area can now use tap water normally, after the latest round of laboratory tests found no E. coli or total coliform bacteria in samples drawn from the reservoir.

The advisory had been in place after microbial contamination was traced to groundwater from the Fountains springs, which normally supplements the reservoir''s Rand Water supply. The city linked the contamination to a damaged sewer pipe in Groenkloof. While repairs to that pipe continued, crews switched the affected network onto the Salvokop Reservoir, then chlorine-shock treated and retested the distribution system before confirming it was safe.

Moya said the groundwater feed from the Fountains springs would stay out of use and the Findlay pipeline would be flushed before it resumes supplying the network. She added that the CBD contamination is a separate matter from the ongoing investigation into a gastroenteritis outbreak in Bronkhorstspruit, where the water treatment plant''s manager has been suspended while that inquiry continues.',
  NULL, NULL, NULL,
  '["https://www.citizen.co.za/news/city-of-tshwane-pretoria-cbd-tap-water-bronkhorstspruit/", "https://www.ewn.co.za/2026/10/24/tshwane-declares-tap-water-in-cbd-safe-to-drink"]',
  'agent'
);
INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'sundowns-knocked-out-caf-champions-league-wiliete-2026-10-23',
  'Sundowns knocked out of CAF Champions League by Wiliete',
  'Sport', '2026-10-23', 'TimesLIVE', 'https://www.timeslive.co.za/sport/soccer/2026-10-23-sundowns-knocked-out-of-the-champions-league-by-wiliete-sc-of-angola/',
  'Defending champions Mamelodi Sundowns were eliminated from the CAF Champions League on away goals after a 1-1 draw with Angola''s Wiliete at Loftus on Friday.',
  'Mamelodi Sundowns'' defence of the CAF Champions League ended in the preliminary round on Friday night, after Angola''s Wiliete SC held them to a 1-1 draw at Loftus Versfeld in Pretoria. Tashreeq Matthews opened the scoring for Sundowns in the first half, his effort from outside the area deflecting past the goalkeeper off a Wiliete defender.

Wiliete forward Cristovao Paciencia equalised early in the second half, reaching a loose ball after a mis-judged Sundowns back-pass to beat goalkeeper Ronwen Williams. The two legs finished level at 1-1 on aggregate, after the first leg in Angola ended goalless, so Wiliete advanced on the away-goals rule.

It is the first time since 2015 that Sundowns have failed to reach the group stage of Africa''s premier club competition, a run of group-stage appearances that began the year after their first continental title in 2016. With the Brazilians out, Orlando Pirates are now South Africa''s only side left in this season''s competition.',
  NULL, NULL, NULL,
  '["https://www.timeslive.co.za/sport/soccer/2026-10-23-sundowns-knocked-out-of-the-champions-league-by-wiliete-sc-of-angola/", "https://www.sabcnews.com/sabcnews/mamelodi-sundowns-knocked-out-of-caf-champions-league/"]',
  'agent'
);
